#include <hwy/highway.h>
#include "stdlib/blas/base/shared.h"


HWY_BEFORE_NAMESPACE();
namespace HWY_NAMESPACE {
	namespace hn = hwy::HWY_NAMESPACE;

	void daxpy_kernel_simd( CBLAS_INT N, double alpha, const double *X, const CBLAS_INT offsetX, double *Y, const CBLAS_INT offsetY ) {
		X += offsetX;
		Y += offsetY;

		const hn::ScalableTag<double> d;
		const auto alpha_vec = hn::Set( d, alpha );

		CBLAS_INT i = 0;
		const CBLAS_INT lanes = static_cast<CBLAS_INT>( hn::Lanes( d ) );
		const CBLAS_INT max_i = N - ( N % lanes );

		for ( ; i < max_i; i += lanes ) {
			const auto x = hn::LoadU( d, X + i );
			const auto y = hn::LoadU( d, Y + i );
			const auto result = hn::MulAdd( alpha_vec, x, y );
			hn::StoreU( result, d, Y + i );
		}

		for ( ; i < N; ++i ) {
			Y[i] += alpha * X[i];
		}
	}

	void daxpy_strided_kernel( CBLAS_INT N, double alpha, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, double *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY ) {
		CBLAS_INT ix;
		CBLAS_INT iy;
		CBLAS_INT i;

		if ( N <= 0 ) {
			return;
		}
		// If `alpha` is `0`, then `y` is unchanged...
		if ( alpha == 0.0 ) {
			return;
		}
		ix = offsetX;
		iy = offsetY;
		for ( i = 0; i < N; i++ ) {
			Y[ iy ] += alpha * X[ ix ];
			ix += strideX;
			iy += strideY;
		}
		return;
	}
} // namespace HWY_NAMESPACE
HWY_AFTER_NAMESPACE();
